import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    lines = raw_csv.splitlines(keepends=True)
    start = 0
    while start < len(lines):
        line = lines[start]
        if not line.strip() or line.lstrip().startswith("#"):
            start += 1
        else:
            break

    if start == len(lines):
        return {"columns": [], "rows": []}

    text = "".join(lines[start:])
    old_limit = csv.field_size_limit()
    try:
        if len(text) > old_limit:
            csv.field_size_limit(len(text))
        records = list(csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([3, len(columns)] + [len(row) for row in rows])

    used = set(columns)
    extra_number = 1
    while len(columns) < width:
        name = "extra_{}".format(extra_number)
        extra_number += 1
        if name not in used:
            columns.append(name)
            used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
